#!/usr/bin/env bash
# Shared settings and helpers for launch.sh, doctor.sh and cleanup.sh. Source it, do not run it.
# Generated by visual-parity scaffold_verify.py; edit the values here, not in the other scripts.
APP="__APP__"
OUT="${VERIFY_OUT:-/tmp/verify-__APP__}"
PORT=__PORT__
HOST=__HOST__
SCHEME=__SCHEME__
ENTRY_URL="$SCHEME://$HOST:$PORT__ENTRY__"
START_CMD="__START__"
READY_TIMEOUT=__TIMEOUT__
PID_FILE="$OUT/dev.pid"

# HTTP status of the entry page, pinned to loopback and bypassing any proxy.
probe() {
  curl --noproxy '*' --resolve "$HOST:$PORT:127.0.0.1" -sk -o /dev/null -w '%{http_code}' "$ENTRY_URL" || true
}

port_listener() { lsof -nP -iTCP:"$PORT" -sTCP:LISTEN -t 2>/dev/null | head -1; }

descendants() {
  local child
  for child in $(pgrep -P "$1" 2>/dev/null); do
    echo "$child"
    descendants "$child"
  done
}

# True when $1 is $2 or below it in the process tree.
is_descendant() {
  local p=$1
  while [ -n "$p" ] && [ "$p" != 0 ] && [ "$p" != 1 ]; do
    [ "$p" = "$2" ] && return 0
    p=$(ps -o ppid= -p "$p" 2>/dev/null | tr -d ' ')
  done
  return 1
}

proc_start()   { ps -p "$1" -o lstart= 2>/dev/null | sed 's/^[[:space:]]*//'; }
proc_command() { ps -p "$1" -o command= 2>/dev/null | sed 's/^[[:space:]]*//'; }

# The pid file holds three lines: pid, start time, command line.
write_pid_file() {
  printf '%s\n%s\n%s\n' "$1" "$(proc_start "$1")" "$(proc_command "$1")" > "$PID_FILE"
}
file_pid() { sed -n '1p' "$PID_FILE" 2>/dev/null; }

# True only when the recorded pid is still the same process that launch.sh started.
pid_file_matches() {
  local pid start cmd
  pid=$(file_pid); start=$(sed -n '2p' "$PID_FILE" 2>/dev/null); cmd=$(sed -n '3p' "$PID_FILE" 2>/dev/null)
  [ -n "$pid" ] && [ -n "$start" ] && [ -n "$cmd" ] || return 1
  [ "$(proc_start "$pid")" = "$start" ] && [ "$(proc_command "$pid")" = "$cmd" ]
}
